def build_next(pattern):
    n = len(pattern)
    nxt = [0] * n
    k = 0
    for i in range(1, n):
        while k > 0 and pattern[i] != pattern[k]:
            k = nxt[k - 1]
        if pattern[i] == pattern[k]:
            k += 1
        nxt[i] = k
    return nxt

def kmp_find(text, pattern):
    if len(pattern) == 0:
        return 0
    nxt = build_next(pattern)
    j = 0
    for i in range(len(text)):
        while j > 0 and text[i] != pattern[j]:
            j = nxt[j - 1]
        if text[i] == pattern[j]:
            j += 1
        if j == len(pattern):
            return i - len(pattern) + 1
    return -1

def is_rotation(s, t):
    if len(s) != len(t):
        return False
    if len(s) == 0:
        return True
    return kmp_find(s + s, t) != -1

print(is_rotation('abc', 'cab'))
print(is_rotation('abc', 'acb'))
print(is_rotation('', ''))
print(is_rotation('abcabc', 'bcabca'))
